'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { CSSProperties, ReactNode } from 'react'
import './lenticular-panel.css'

export interface LenticularPanelProps {
  /** Decorative artwork only; interactive children are intentionally inert. */
  front: ReactNode
  /** Decorative artwork only; interactive children are intentionally inert. */
  back: ReactNode
  frontLabel?: string
  backLabel?: string
  /** The number of vertical lenses, clamped to 4–24. */
  segments?: number
  /** The initial viewing angle: 0 shows the front and 1 shows the back. */
  defaultValue?: number
  className?: string
  onValueChange?: (value: number) => void
}

function clamp(value: number) {
  return Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : 0
}

/** A two-sided print divided into rotating lenses, with an accessible angle control. */
export function LenticularPanel({
  front,
  back,
  frontLabel = 'First artwork',
  backLabel = 'Second artwork',
  segments = 12,
  defaultValue = 0,
  className = '',
  onValueChange,
}: LenticularPanelProps) {
  const id = useId()
  const lensCount = Number.isFinite(segments) ? Math.max(4, Math.min(24, Math.round(segments))) : 12
  const [value, setValue] = useState(() => clamp(defaultValue))
  const [reducedMotion, setReducedMotion] = useState(false)
  const pointerEnabled = useRef(false)
  const frame = useRef<number | null>(null)
  const pendingValue = useRef(value)
  const currentValue = useRef(value)
  const changeCallback = useRef(onValueChange)

  useEffect(() => {
    changeCallback.current = onValueChange
  }, [onValueChange])

  useEffect(() => {
    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)')
    const pointerQuery = window.matchMedia('(hover: hover) and (pointer: fine)')
    function updatePreferences() {
      pointerEnabled.current = pointerQuery.matches && !motionQuery.matches
      setReducedMotion(motionQuery.matches)
      if (!pointerEnabled.current && frame.current !== null) {
        cancelAnimationFrame(frame.current)
        frame.current = null
      }
    }
    updatePreferences()
    motionQuery.addEventListener('change', updatePreferences)
    pointerQuery.addEventListener('change', updatePreferences)
    return () => {
      motionQuery.removeEventListener('change', updatePreferences)
      pointerQuery.removeEventListener('change', updatePreferences)
      if (frame.current !== null) cancelAnimationFrame(frame.current)
    }
  }, [])

  function commitValue(next: number) {
    const safeValue = clamp(next)
    if (safeValue === currentValue.current) return
    currentValue.current = safeValue
    setValue(safeValue)
    changeCallback.current?.(safeValue)
  }

  function setImmediateValue(next: number) {
    if (frame.current !== null) {
      cancelAnimationFrame(frame.current)
      frame.current = null
    }
    commitValue(next)
  }

  const visibleValue = reducedMotion ? Number(value >= 0.5) : value
  const artworkLabel = value < 0.5 ? frontLabel : backLabel
  const panelStyle = {
    '--ac-lenticular-segments': lensCount,
    '--ac-lenticular-angle': `${visibleValue * -180}deg`,
    '--ac-lenticular-wave': `${Math.sin(visibleValue * Math.PI) * 22}deg`,
    '--ac-lenticular-glint': Math.sin(visibleValue * Math.PI).toFixed(3),
  } as CSSProperties

  return (
    <section className={`ac-lenticular-panel ${className}`.trim()} style={panelStyle} data-side={value < 0.5 ? 'front' : 'back'} aria-label="Lenticular print">
      <div className="ac-lenticular-heading" aria-hidden="true">
        <span>Two views. One surface.</span>
        <span>{String(Math.round(value * 180)).padStart(3, '0')}°</span>
      </div>
      <div
        className="ac-lenticular-print"
        aria-hidden="true"
        onPointerMove={(event) => {
          if (event.pointerType === 'touch' || !pointerEnabled.current) return
          const bounds = event.currentTarget.getBoundingClientRect()
          if (bounds.width <= 0) return
          pendingValue.current = clamp((event.clientX - bounds.left) / bounds.width)
          if (frame.current !== null) return
          frame.current = requestAnimationFrame(() => {
            frame.current = null
            commitValue(pendingValue.current)
          })
        }}
      >
        <div className="ac-lenticular-lenses" ref={(element) => { element?.setAttribute('inert', '') }}>
          {Array.from({ length: lensCount }, (_, index) => (
            <div className="ac-lenticular-lens" key={index} style={{ '--ac-lenticular-index': index, '--ac-lenticular-phase': index / (lensCount - 1) - 0.5 } as CSSProperties}>
              <div className="ac-lenticular-face ac-lenticular-face-front">
                <div className="ac-lenticular-artwork">{front}</div>
              </div>
              <div className="ac-lenticular-face ac-lenticular-face-back">
                <div className="ac-lenticular-artwork">{back}</div>
              </div>
            </div>
          ))}
        </div>
        <div className="ac-lenticular-glass" />
      </div>
      <div className="ac-lenticular-controls">
        <div className="ac-lenticular-control-heading">
          <label htmlFor={`${id}-angle`}>Viewing angle</label>
          <span aria-hidden="true">{Math.round(value * 100)}%</span>
        </div>
        <input
          id={`${id}-angle`}
          className="ac-lenticular-range"
          type="range"
          min={0}
          max={100}
          step={1}
          value={Math.round(value * 100)}
          aria-describedby={`${id}-instructions`}
          aria-valuetext={reducedMotion ? artworkLabel : `${Math.round(value * 100)}%, ${artworkLabel}`}
          onChange={(event) => setImmediateValue(Number(event.currentTarget.value) / 100)}
        />
        <div className="ac-lenticular-endpoints">
          <button type="button" onClick={() => setImmediateValue(0)} aria-pressed={value === 0}>
            <span aria-hidden="true">↙</span> {frontLabel}
          </button>
          <button type="button" onClick={() => setImmediateValue(1)} aria-pressed={value === 1}>
            {backLabel} <span aria-hidden="true">↗</span>
          </button>
        </div>
        <p className="ac-lenticular-instructions" id={`${id}-instructions`}>
          {reducedMotion ? 'Adjust the viewing angle to switch artwork.' : 'Move across the print, or adjust the viewing angle.'}
        </p>
      </div>
    </section>
  )
}

.ac-lenticular-panel {
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto minmax(120px, 1fr) auto;
  gap: 11px;
  width: 100%;
  height: var(--ac-lenticular-height, 360px);
  min-height: 280px;
  padding: var(--ac-lenticular-padding, 17px 20px 12px);
  overflow: hidden;
  background: var(--ac-lenticular-background, #eae7de);
  color: var(--ac-lenticular-color, #252722);
  text-align: left;
}

.ac-lenticular-heading,
.ac-lenticular-control-heading,
.ac-lenticular-endpoints,
.ac-lenticular-instructions {
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 9px;
  line-height: 1.4;
}

.ac-lenticular-heading,
.ac-lenticular-control-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.ac-lenticular-heading {
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.ac-lenticular-print {
  position: relative;
  min-width: 0;
  min-height: 0;
  border: 1px solid #151712;
  background: var(--ac-lenticular-groove, #252722);
  box-shadow: 3px 4px 0 #2527221a, 0 8px 18px #25272212;
  perspective: 1800px;
  touch-action: pan-y;
  cursor: ew-resize;
}

.ac-lenticular-lenses {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: repeat(var(--ac-lenticular-segments), minmax(0, 1fr));
  transform-style: preserve-3d;
  pointer-events: none;
}

.ac-lenticular-lens {
  position: relative;
  min-width: 0;
  height: 100%;
  transform: rotateY(calc(var(--ac-lenticular-angle) + var(--ac-lenticular-phase) * var(--ac-lenticular-wave)));
  transform-style: preserve-3d;
  transition: transform 100ms linear;
}

.ac-lenticular-face {
  position: absolute;
  inset: 0;
  overflow: hidden;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  background: var(--ac-lenticular-groove, #252722);
  transform: translateZ(0.5px);
}

.ac-lenticular-face-back {
  transform: rotateY(180deg) translateZ(0.5px);
}

.ac-lenticular-artwork {
  position: relative;
  width: calc(100% * var(--ac-lenticular-segments));
  height: 100%;
  overflow: hidden;
  transform: translateX(calc(var(--ac-lenticular-index) * -100% / var(--ac-lenticular-segments)));
  pointer-events: none;
  user-select: none;
}

.ac-lenticular-artwork > * {
  display: block;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  margin: 0;
}

.ac-lenticular-artwork img,
.ac-lenticular-artwork video {
  object-fit: cover;
}

.ac-lenticular-face::after {
  position: absolute;
  inset: 0;
  border-inline: 1px solid #14161024;
  background: linear-gradient(90deg, #ffffff14, transparent 20%, transparent 70%, #0000001c);
  content: '';
}

.ac-lenticular-glass {
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 30%, #ffffff45 50%, transparent 70%);
  opacity: calc(0.05 + var(--ac-lenticular-glint) * 0.25);
  pointer-events: none;
}

.ac-lenticular-controls {
  min-width: 0;
}

.ac-lenticular-control-heading {
  gap: 10px;
}

.ac-lenticular-control-heading label {
  font-weight: 600;
}

.ac-lenticular-range {
  display: block;
  width: 100%;
  height: 22px;
  margin: 0;
  accent-color: var(--ac-lenticular-accent, #df5b39);
  cursor: ew-resize;
}

.ac-lenticular-range:focus-visible,
.ac-lenticular-endpoints button:focus-visible {
  outline: 2px solid var(--ac-lenticular-focus, #293feb);
  outline-offset: 3px;
  border-radius: 2px;
}

.ac-lenticular-endpoints {
  display: flex;
  justify-content: space-between;
  gap: 14px;
}

.ac-lenticular-endpoints button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 44px;
  min-height: 44px;
  max-width: calc(50% - 7px);
  padding: 3px 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: inherit;
  text-wrap: balance;
  cursor: pointer;
  opacity: 0.67;
}

.ac-lenticular-endpoints button[aria-pressed='true'] {
  opacity: 1;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.ac-lenticular-instructions {
  margin: 2px 0 0;
  font-size: 8px;
  opacity: 0.62;
}

@media (prefers-reduced-motion: reduce) {
  .ac-lenticular-lens {
    transform: rotateY(0deg);
    transition: none;
  }

  .ac-lenticular-face-back {
    transform: translateZ(0.5px);
    visibility: hidden;
  }

  .ac-lenticular-panel[data-side='back'] .ac-lenticular-face-front {
    visibility: hidden;
  }

  .ac-lenticular-panel[data-side='back'] .ac-lenticular-face-back {
    visibility: visible;
  }

  .ac-lenticular-print {
    cursor: default;
  }
}
